#!/usr/bin/env bash
set -euo pipefail

# ----------------------------------------------------------------------
# Run many MetaCS-FL experiments from a generated manifest.
#
# This script is intentionally manifest-driven. It does not define packs.
# Packs are generated by:
#
#   scripts/execution/generate_experiment_pack.py
#
# Main responsibilities:
#   - generate or read campaign_manifest.csv
#   - provide fault tolerance through completed/failed/running markers
#   - dispatch distributed_flower rows to run_one_distributed_experiment.sh
#   - dispatch server_only_python rows to run_on_server_only.sh
# ----------------------------------------------------------------------

usage() {
  cat <<'EOF'
Usage:
  run_many_distributed_experiments.sh --campaign-id ID --nodes-file FILE [options]

Manifest options:
  --manifest FILE
      Existing campaign manifest CSV.
      If omitted, --pack must be provided and the manifest is generated.

  --pack fgcs_2026_experiments
      Experiment pack to generate through generate_experiment_pack.py.

  --experiments-root DIR
      Experiments root used by the generator.
      Default: experiments

  --generate-pack-script FILE
      Pack generator script.
      Default: scripts/execution/generate_experiment_pack.py

Required:
  --campaign-id ID
      Campaign identifier. Used for state, logs, gathered outputs, and merged outputs.

  --nodes-file FILE
      Node description file shared by setup and launch scripts.

Main options:
  --remote-project-dir DIR
      Project directory on target nodes.
      Default: /root/metacs-fl

  --remote-venv-activate FILE
      Virtual environment activation script on target nodes.
      Default: <remote-project-dir>/.venv/bin/activate

  --install true|false
      Whether run_one_distributed_experiment.sh should run setup before distributed experiments.
      Default: false

  --dry-run true|false
      Generate/validate the manifest, print summary, and do not execute experiments.
      Default: false

Fault tolerance:
  --force-rerun true|false
      Run experiments even when completed markers exist.
      Default: false

  --rerun-failed true|false
      Retry experiments with failed markers.
      Default: true

  --rerun-running true|false
      Retry experiments left in running state by a previous interrupted campaign.
      Default: true

Execution:
  --max-parallel-experiments N
      Number of experiments to run in parallel.
      Default: 1

  --repetitions N
      Passed to distributed experiments.
      Default: 1

  --max-parallel-installs N
      Passed to setup via run_one_distributed_experiment.sh.
      Default: 4

  --max-parallel-remote-ops N
      Passed to distributed launcher via run_one_distributed_experiment.sh.
      Default: 8

Script paths:
  --run-one-script FILE
      Default: scripts/execution/run_one_distributed_experiment.sh

  --run-server-only-script FILE
      Default: scripts/execution/run_on_server_only.sh

Common:
  --python-bin BIN
      Default: python3

  --ssh-options "OPTIONS"
      Extra SSH options.
      Default: empty

  --rsync-options "OPTIONS"
      Extra rsync options.
      Default: -az

Repository/setup options for distributed experiments:
  --repo-url URL
      Default: https://github.com/alan-lira/metacs-fl.git

  --branch BRANCH
      Default: main

  --repo-auth none|token|ssh
      Default: none

  --prompt-github-token true|false
      Default: true

  --force-reclone true|false
      Default: true

  --install-powerjoular true|false
      Default: true

  --append-venv-to-bashrc true|false
      Default: true

  --install-metacsfl-package true|false
      Default: true

Output roots:
  --campaign-root DIR
      Default: campaign_runs

  --distributed-log-root DIR
      Default: distributed_launch_logs

  --gather-root DIR
      Default: gathered_results

  --merge-root DIR
      Default: merged_results

  --server-only-log-root DIR
      Default: server_only_logs

  --server-only-output-root DIR
      Default: server_only_results

  -h, --help
      Show help.

Examples:

  Generate manifest and dry-run:
    bash scripts/execution/run_many_distributed_experiments.sh \
      --pack fgcs_2026_experiments \
      --campaign-id fgcs_2026_dry_run_001 \
      --nodes-file scripts/nodes.g5k.txt \
      --dry-run true

  Run using generated pack:
    bash scripts/execution/run_many_distributed_experiments.sh \
      --pack fgcs_2026_experiments \
      --campaign-id fgcs_2026_experiments_001 \
      --nodes-file scripts/nodes.g5k.txt \
      --remote-project-dir /root/metacs-fl \
      --install false \
      --max-parallel-experiments 1 \
      --max-parallel-remote-ops 8

  Run using an existing manifest:
    bash scripts/execution/run_many_distributed_experiments.sh \
      --manifest campaign_runs/fgcs_2026_experiments_001/campaign_manifest.csv \
      --campaign-id fgcs_2026_experiments_001 \
      --nodes-file scripts/nodes.g5k.txt \
      --remote-project-dir /root/metacs-fl \
      --install false
EOF
}

# ----------------------------------------------------------------------
# Helpers
# ----------------------------------------------------------------------

die() {
  echo "ERROR: $*" >&2
  exit 1
}

warn() {
  echo "WARNING: $*" >&2
}

require_value() {
  local opt="$1"
  local val="${2:-}"

  if [[ -z "${val}" || "${val}" == --* ]]; then
    die "${opt} requires a value"
  fi
}

bool_check() {
  local name="$1"
  local value="$2"

  if [[ "${value}" != "true" && "${value}" != "false" ]]; then
    die "${name} must be true or false"
  fi
}

positive_int_check() {
  local name="$1"
  local value="$2"

  if ! [[ "${value}" =~ ^[0-9]+$ ]]; then
    die "${name} must be a positive integer"
  fi

  if [[ "${value}" -lt 1 ]]; then
    die "${name} must be >= 1"
  fi
}

sanitize_name() {
  echo "$1" | sed 's/[^A-Za-z0-9_.-]/_/g'
}

wait_for_available_slot() {
  local max_jobs="$1"

  while true; do
    local running
    running="$(jobs -pr | wc -l)"

    if [[ "${running}" -lt "${max_jobs}" ]]; then
      break
    fi

    sleep 1
  done
}

mark_json() {
  local path="$1"
  local status="$2"
  local experiment_id="$3"
  local run_id="$4"
  local backend="$5"
  local started_at="$6"
  local finished_at="$7"
  local log_file="$8"

  cat > "${path}" <<EOF
{
  "status": "${status}",
  "experiment_id": "${experiment_id}",
  "run_id": "${run_id}",
  "backend": "${backend}",
  "started_at": "${started_at}",
  "finished_at": "${finished_at}",
  "log_file": "${log_file}"
}
EOF
}

# ----------------------------------------------------------------------
# Defaults
# ----------------------------------------------------------------------

MANIFEST=""
PACK=""
EXPERIMENTS_ROOT="experiments"
GENERATE_PACK_SCRIPT="scripts/execution/generate_experiment_pack.py"

CAMPAIGN_ID=""
NODES_FILE=""

REMOTE_PROJECT_DIR="/root/metacs-fl"
REMOTE_VENV_ACTIVATE=""

INSTALL="false"
DRY_RUN="false"

FORCE_RERUN="false"
RERUN_FAILED="true"
RERUN_RUNNING="true"

MAX_PARALLEL_EXPERIMENTS="1"
REPETITIONS="1"
MAX_PARALLEL_INSTALLS="4"
MAX_PARALLEL_REMOTE_OPS="8"

RUN_ONE_SCRIPT="scripts/execution/run_one_distributed_experiment.sh"
RUN_SERVER_ONLY_SCRIPT="scripts/execution/run_on_server_only.sh"

PYTHON_BIN="python3"
SSH_OPTIONS=""
RSYNC_OPTIONS="-az"

REPO_URL="https://github.com/alan-lira/metacs-fl.git"
BRANCH="main"
REPO_AUTH="none"
PROMPT_GITHUB_TOKEN="true"
FORCE_RECLONE="true"
INSTALL_POWERJOULAR="true"
APPEND_VENV_TO_BASHRC="true"
INSTALL_METACSFL_PACKAGE="true"

CAMPAIGN_ROOT="campaign_runs"
DISTRIBUTED_LOG_ROOT="distributed_launch_logs"
GATHER_ROOT="gathered_results"
MERGE_ROOT="merged_results"
SERVER_ONLY_LOG_ROOT="server_only_logs"
SERVER_ONLY_OUTPUT_ROOT="server_only_results"

# ----------------------------------------------------------------------
# Parse args
# ----------------------------------------------------------------------

while [[ "$#" -gt 0 ]]; do
  case "$1" in
    --manifest)
      require_value "$1" "${2:-}"
      MANIFEST="$2"
      shift 2
      ;;

    --pack)
      require_value "$1" "${2:-}"
      PACK="$2"
      shift 2
      ;;

    --experiments-root)
      require_value "$1" "${2:-}"
      EXPERIMENTS_ROOT="$2"
      shift 2
      ;;

    --generate-pack-script)
      require_value "$1" "${2:-}"
      GENERATE_PACK_SCRIPT="$2"
      shift 2
      ;;

    --campaign-id)
      require_value "$1" "${2:-}"
      CAMPAIGN_ID="$2"
      shift 2
      ;;

    --nodes-file)
      require_value "$1" "${2:-}"
      NODES_FILE="$2"
      shift 2
      ;;

    --remote-project-dir)
      require_value "$1" "${2:-}"
      REMOTE_PROJECT_DIR="$2"
      shift 2
      ;;

    --remote-venv-activate)
      require_value "$1" "${2:-}"
      REMOTE_VENV_ACTIVATE="$2"
      shift 2
      ;;

    --install)
      require_value "$1" "${2:-}"
      INSTALL="$2"
      shift 2
      ;;

    --dry-run)
      require_value "$1" "${2:-}"
      DRY_RUN="$2"
      shift 2
      ;;

    --force-rerun)
      require_value "$1" "${2:-}"
      FORCE_RERUN="$2"
      shift 2
      ;;

    --rerun-failed)
      require_value "$1" "${2:-}"
      RERUN_FAILED="$2"
      shift 2
      ;;

    --rerun-running)
      require_value "$1" "${2:-}"
      RERUN_RUNNING="$2"
      shift 2
      ;;

    --max-parallel-experiments)
      require_value "$1" "${2:-}"
      MAX_PARALLEL_EXPERIMENTS="$2"
      shift 2
      ;;

    --repetitions)
      require_value "$1" "${2:-}"
      REPETITIONS="$2"
      shift 2
      ;;

    --max-parallel-installs)
      require_value "$1" "${2:-}"
      MAX_PARALLEL_INSTALLS="$2"
      shift 2
      ;;

    --max-parallel-remote-ops)
      require_value "$1" "${2:-}"
      MAX_PARALLEL_REMOTE_OPS="$2"
      shift 2
      ;;

    --run-one-script)
      require_value "$1" "${2:-}"
      RUN_ONE_SCRIPT="$2"
      shift 2
      ;;

    --run-server-only-script)
      require_value "$1" "${2:-}"
      RUN_SERVER_ONLY_SCRIPT="$2"
      shift 2
      ;;

    --python-bin)
      require_value "$1" "${2:-}"
      PYTHON_BIN="$2"
      shift 2
      ;;

    --ssh-options)
      require_value "$1" "${2:-}"
      SSH_OPTIONS="$2"
      shift 2
      ;;

    --rsync-options)
      require_value "$1" "${2:-}"
      RSYNC_OPTIONS="$2"
      shift 2
      ;;

    --repo-url)
      require_value "$1" "${2:-}"
      REPO_URL="$2"
      shift 2
      ;;

    --branch)
      require_value "$1" "${2:-}"
      BRANCH="$2"
      shift 2
      ;;

    --repo-auth)
      require_value "$1" "${2:-}"
      REPO_AUTH="$2"
      shift 2
      ;;

    --prompt-github-token)
      require_value "$1" "${2:-}"
      PROMPT_GITHUB_TOKEN="$2"
      shift 2
      ;;

    --force-reclone)
      require_value "$1" "${2:-}"
      FORCE_RECLONE="$2"
      shift 2
      ;;

    --install-powerjoular)
      require_value "$1" "${2:-}"
      INSTALL_POWERJOULAR="$2"
      shift 2
      ;;

    --append-venv-to-bashrc)
      require_value "$1" "${2:-}"
      APPEND_VENV_TO_BASHRC="$2"
      shift 2
      ;;

    --install-metacsfl-package)
      require_value "$1" "${2:-}"
      INSTALL_METACSFL_PACKAGE="$2"
      shift 2
      ;;

    --campaign-root)
      require_value "$1" "${2:-}"
      CAMPAIGN_ROOT="$2"
      shift 2
      ;;

    --distributed-log-root)
      require_value "$1" "${2:-}"
      DISTRIBUTED_LOG_ROOT="$2"
      shift 2
      ;;

    --gather-root)
      require_value "$1" "${2:-}"
      GATHER_ROOT="$2"
      shift 2
      ;;

    --merge-root)
      require_value "$1" "${2:-}"
      MERGE_ROOT="$2"
      shift 2
      ;;

    --server-only-log-root)
      require_value "$1" "${2:-}"
      SERVER_ONLY_LOG_ROOT="$2"
      shift 2
      ;;

    --server-only-output-root)
      require_value "$1" "${2:-}"
      SERVER_ONLY_OUTPUT_ROOT="$2"
      shift 2
      ;;

    -h|--help)
      usage
      exit 0
      ;;

    *)
      echo "ERROR: unknown argument: $1" >&2
      echo >&2
      usage >&2
      exit 1
      ;;
  esac
done

# ----------------------------------------------------------------------
# Validate
# ----------------------------------------------------------------------

[[ -n "${CAMPAIGN_ID}" ]] || die "--campaign-id is required"
[[ -n "${NODES_FILE}" ]] || die "--nodes-file is required"
[[ -f "${NODES_FILE}" ]] || die "nodes file not found: ${NODES_FILE}"
[[ -f "${RUN_ONE_SCRIPT}" ]] || die "run-one script not found: ${RUN_ONE_SCRIPT}"
[[ -f "${RUN_SERVER_ONLY_SCRIPT}" ]] || die "server-only script not found: ${RUN_SERVER_ONLY_SCRIPT}"

if [[ -z "${MANIFEST}" && -z "${PACK}" ]]; then
  die "provide either --manifest FILE or --pack PACK_NAME"
fi

if [[ -n "${MANIFEST}" && -n "${PACK}" ]]; then
  die "provide only one of --manifest or --pack"
fi

bool_check "--install" "${INSTALL}"
bool_check "--dry-run" "${DRY_RUN}"
bool_check "--force-rerun" "${FORCE_RERUN}"
bool_check "--rerun-failed" "${RERUN_FAILED}"
bool_check "--rerun-running" "${RERUN_RUNNING}"
bool_check "--prompt-github-token" "${PROMPT_GITHUB_TOKEN}"
bool_check "--force-reclone" "${FORCE_RECLONE}"
bool_check "--install-powerjoular" "${INSTALL_POWERJOULAR}"
bool_check "--append-venv-to-bashrc" "${APPEND_VENV_TO_BASHRC}"
bool_check "--install-metacsfl-package" "${INSTALL_METACSFL_PACKAGE}"

positive_int_check "--max-parallel-experiments" "${MAX_PARALLEL_EXPERIMENTS}"
positive_int_check "--repetitions" "${REPETITIONS}"
positive_int_check "--max-parallel-installs" "${MAX_PARALLEL_INSTALLS}"
positive_int_check "--max-parallel-remote-ops" "${MAX_PARALLEL_REMOTE_OPS}"

if [[ -z "${REMOTE_VENV_ACTIVATE}" ]]; then
  REMOTE_VENV_ACTIVATE="${REMOTE_PROJECT_DIR}/.venv/bin/activate"
fi

# ----------------------------------------------------------------------
# Campaign directories
# ----------------------------------------------------------------------

CAMPAIGN_DIR="${CAMPAIGN_ROOT}/${CAMPAIGN_ID}"
STATE_DIR="${CAMPAIGN_DIR}/state"
COMPLETED_DIR="${STATE_DIR}/completed"
FAILED_DIR="${STATE_DIR}/failed"
RUNNING_DIR="${STATE_DIR}/running"
LOG_DIR="${CAMPAIGN_DIR}/logs"
SUMMARY_DIR="${CAMPAIGN_DIR}/summaries"

mkdir -p "${COMPLETED_DIR}" "${FAILED_DIR}" "${RUNNING_DIR}" "${LOG_DIR}" "${SUMMARY_DIR}"

if [[ -z "${MANIFEST}" ]]; then
  [[ -f "${GENERATE_PACK_SCRIPT}" ]] || die "pack generator not found: ${GENERATE_PACK_SCRIPT}"

  MANIFEST="${CAMPAIGN_DIR}/campaign_manifest.csv"
  SUMMARY_JSON="${CAMPAIGN_DIR}/campaign_manifest.summary.json"

  echo "[CAMPAIGN] Generating manifest for pack: ${PACK}"

  "${PYTHON_BIN}" "${GENERATE_PACK_SCRIPT}" \
    --pack "${PACK}" \
    --experiments-root "${EXPERIMENTS_ROOT}" \
    --output "${MANIFEST}" \
    --summary-output "${SUMMARY_JSON}" \
    --validate true
else
  [[ -f "${MANIFEST}" ]] || die "manifest not found: ${MANIFEST}"
fi

SUMMARY_CSV="${SUMMARY_DIR}/campaign_summary.csv"
ROWS_USV="${CAMPAIGN_DIR}/campaign_manifest.rows.usv"

# ----------------------------------------------------------------------
# Convert manifest CSV to Unit-Separator-delimited rows for Bash.
#
# IMPORTANT:
#   Do not use TSV here. Bash treats tabs in IFS as whitespace and collapses
#   consecutive separators, which destroys empty CSV fields. Server-only rows
#   intentionally have empty distributed config columns, so preserving empty
#   fields is mandatory.
# ----------------------------------------------------------------------

ROW_COUNT="$(
  "${PYTHON_BIN}" - "${MANIFEST}" "${ROWS_USV}" <<'PY'
from __future__ import annotations

import csv
import sys
from pathlib import Path

manifest = Path(sys.argv[1])
output = Path(sys.argv[2])

required = [
    "experiment_id",
    "backend",
    "group",
    "num_clients",
    "dataset",
    "distribution",
    "approach",
    "executor_cfg",
    "server_cfg",
    "client_cfg",
    "server_script",
    "server_config",
    "remote_output_dir",
]

sep = "\x1f"

with manifest.open("r", encoding="utf-8-sig", newline="") as f:
    reader = csv.DictReader(f)

    if reader.fieldnames is None:
        raise SystemExit("Manifest has no header")

    missing = [c for c in required if c not in reader.fieldnames]
    if missing:
        raise SystemExit(f"Manifest missing required columns: {missing}")

    rows = list(reader)

with output.open("w", encoding="utf-8") as f:
    for row in rows:
        values = []
        for col in required:
            value = row.get(col, "")
            if sep in value or "\n" in value or "\r" in value:
                raise SystemExit(
                    f"Unsupported separator/newline in manifest field {col}: {value!r}"
                )
            values.append(value)
        f.write(sep.join(values) + "\n")

print(len(rows))
PY
)"

mapfile -t ROWS < "${ROWS_USV}"
TOTAL="${#ROWS[@]}"

if [[ "${ROW_COUNT}" != "${TOTAL}" ]]; then
  die "internal manifest conversion mismatch: python_count=${ROW_COUNT}, bash_count=${TOTAL}"
fi

echo "[CAMPAIGN] Campaign ID: ${CAMPAIGN_ID}"
echo "[CAMPAIGN] Manifest: ${MANIFEST}"
echo "[CAMPAIGN] Internal rows file: ${ROWS_USV}"
echo "[CAMPAIGN] Total experiments: ${TOTAL}"
echo "[CAMPAIGN] State dir: ${STATE_DIR}"
echo "[CAMPAIGN] Logs: ${LOG_DIR}"

if [[ "${DRY_RUN}" == "true" ]]; then
  echo "[CAMPAIGN] Dry run requested. No experiments will be executed."
  exit 0
fi

# ----------------------------------------------------------------------
# Run one manifest row
# ----------------------------------------------------------------------

run_manifest_row() {
  local row="$1"

  local experiment_id=""
  local backend=""
  local group=""
  local num_clients=""
  local dataset=""
  local distribution=""
  local approach=""
  local executor_cfg=""
  local server_cfg=""
  local client_cfg=""
  local server_script=""
  local server_config=""
  local remote_output_dir=""

  IFS=$'\x1f' read -r \
    experiment_id \
    backend \
    group \
    num_clients \
    dataset \
    distribution \
    approach \
    executor_cfg \
    server_cfg \
    client_cfg \
    server_script \
    server_config \
    remote_output_dir <<< "${row}"

  if [[ -z "${experiment_id}" ]]; then
    echo "ERROR: parsed empty experiment_id from manifest row: ${row}" >&2
    return 1
  fi

  if [[ -z "${backend}" ]]; then
    echo "ERROR: parsed empty backend for experiment_id=${experiment_id}" >&2
    return 1
  fi

  local run_id="${CAMPAIGN_ID}__${experiment_id}"

  local completed_marker="${COMPLETED_DIR}/${experiment_id}.done.json"
  local failed_marker="${FAILED_DIR}/${experiment_id}.failed.json"
  local running_marker="${RUNNING_DIR}/${experiment_id}.running.json"
  local log_file="${LOG_DIR}/${experiment_id}.log"

  if [[ "${FORCE_RERUN}" == "false" && -f "${completed_marker}" ]]; then
    echo "[SKIP] ${experiment_id} already completed."
    return 0
  fi

  if [[ "${FORCE_RERUN}" == "false" && "${RERUN_FAILED}" == "false" && -f "${failed_marker}" ]]; then
    echo "[SKIP] ${experiment_id} previously failed and --rerun-failed=false."
    return 0
  fi

  if [[ "${FORCE_RERUN}" == "false" && "${RERUN_RUNNING}" == "false" && -f "${running_marker}" ]]; then
    echo "[SKIP] ${experiment_id} has running marker and --rerun-running=false."
    return 0
  fi

  rm -f "${failed_marker}"

  local started_at
  started_at="$(date -Is)"

  mark_json \
    "${running_marker}" \
    "running" \
    "${experiment_id}" \
    "${run_id}" \
    "${backend}" \
    "${started_at}" \
    "" \
    "${log_file}"

  echo "[RUN] ${experiment_id} (${backend})"
  echo "[RUN] Log: ${log_file}"

  (
    set -euo pipefail

    echo "======================================================================"
    echo "Experiment: ${experiment_id}"
    echo "Backend: ${backend}"
    echo "Group: ${group}"
    echo "Num clients: ${num_clients}"
    echo "Dataset: ${dataset}"
    echo "Distribution: ${distribution}"
    echo "Approach: ${approach}"
    echo "Run ID: ${run_id}"
    echo "Started at: ${started_at}"
    echo "======================================================================"
    echo

    if [[ "${backend}" == "distributed_flower" ]]; then
      if [[ -z "${executor_cfg}" || -z "${server_cfg}" || -z "${client_cfg}" ]]; then
        echo "ERROR: distributed_flower row requires executor_cfg, server_cfg, and client_cfg" >&2
        exit 1
      fi

      CMD=(
        bash "${RUN_ONE_SCRIPT}"
        --install "${INSTALL}"
        --nodes-file "${NODES_FILE}"
        --remote-project-dir "${REMOTE_PROJECT_DIR}"
        --remote-venv-activate "${REMOTE_VENV_ACTIVATE}"
        --repo-url "${REPO_URL}"
        --branch "${BRANCH}"
        --repo-auth "${REPO_AUTH}"
        --prompt-github-token "${PROMPT_GITHUB_TOKEN}"
        --force-reclone "${FORCE_RECLONE}"
        --install-powerjoular "${INSTALL_POWERJOULAR}"
        --append-venv-to-bashrc "${APPEND_VENV_TO_BASHRC}"
        --install-metacsfl-package "${INSTALL_METACSFL_PACKAGE}"
        --max-parallel-installs "${MAX_PARALLEL_INSTALLS}"
        --run-id "${run_id}"
        --custom-flower-executor-cfg "${executor_cfg}"
        --custom-flower-server-cfg "${server_cfg}"
        --custom-flower-client-cfg "${client_cfg}"
        --patch-executor-config true
        --patch-grpc-config true
        --server-port 8080
        --max-parallel-remote-ops "${MAX_PARALLEL_REMOTE_OPS}"
        --repetitions "${REPETITIONS}"
        --local-log-root "${DISTRIBUTED_LOG_ROOT}"
        --local-gather-root "${GATHER_ROOT}"
        --merge-output-root "${MERGE_ROOT}"
        --clean-merge-output true
        --python-bin "${PYTHON_BIN}"
        --rsync-options "${RSYNC_OPTIONS}"
      )

      if [[ -n "${SSH_OPTIONS}" ]]; then
        CMD+=(--ssh-options "${SSH_OPTIONS}")
      fi

      printf '[CMD]'
      printf ' %q' "${CMD[@]}"
      echo

      "${CMD[@]}"

      if [[ ! -f "${MERGE_ROOT}/${run_id}/merge_report.json" ]]; then
        echo "ERROR: expected merge report not found: ${MERGE_ROOT}/${run_id}/merge_report.json" >&2
        exit 1
      fi

    elif [[ "${backend}" == "server_only_python" ]]; then
      if [[ -z "${server_script}" ]]; then
        echo "ERROR: server_only_python row requires server_script" >&2
        echo "Parsed fields:" >&2
        echo "  experiment_id=${experiment_id}" >&2
        echo "  backend=${backend}" >&2
        echo "  group=${group}" >&2
        echo "  approach=${approach}" >&2
        echo "  server_script=${server_script}" >&2
        echo "  server_config=${server_config}" >&2
        echo "  remote_output_dir=${remote_output_dir}" >&2
        exit 1
      fi

      CMD=(
        bash "${RUN_SERVER_ONLY_SCRIPT}"
        --nodes-file "${NODES_FILE}"
        --remote-project-dir "${REMOTE_PROJECT_DIR}"
        --remote-venv-activate "${REMOTE_VENV_ACTIVATE}"
        --script "${server_script}"
        --run-id "${run_id}"
        --local-log-root "${SERVER_ONLY_LOG_ROOT}"
        --local-output-root "${SERVER_ONLY_OUTPUT_ROOT}"
        --clean-local-output true
        --python-bin "${PYTHON_BIN}"
        --rsync-options "${RSYNC_OPTIONS}"
      )

      if [[ -n "${server_config}" ]]; then
        CMD+=(--config-file "${server_config}")
      fi

      if [[ -n "${remote_output_dir}" ]]; then
        CMD+=(--remote-output-dir "${remote_output_dir}")
      fi

      if [[ -n "${SSH_OPTIONS}" ]]; then
        CMD+=(--ssh-options "${SSH_OPTIONS}")
      fi

      printf '[CMD]'
      printf ' %q' "${CMD[@]}"
      echo

      "${CMD[@]}"

    else
      echo "ERROR: unsupported backend: ${backend}" >&2
      exit 1
    fi
  ) > "${log_file}" 2>&1

  local finished_at
  finished_at="$(date -Is)"

  rm -f "${running_marker}"

  mark_json \
    "${completed_marker}" \
    "completed" \
    "${experiment_id}" \
    "${run_id}" \
    "${backend}" \
    "${started_at}" \
    "${finished_at}" \
    "${log_file}"

  echo "[DONE] ${experiment_id}"
}

# ----------------------------------------------------------------------
# Execute campaign
# ----------------------------------------------------------------------

PIDS=()
declare -A PID_TO_EXPERIMENT=()

FAILED=0

for row in "${ROWS[@]}"; do
  wait_for_available_slot "${MAX_PARALLEL_EXPERIMENTS}"

  # Unit Separator is not shell-whitespace, so this preserves empty columns.
  experiment_id="${row%%$'\x1f'*}"

  (
    set -euo pipefail
    run_manifest_row "${row}"
  ) &

  pid="$!"
  PIDS+=("${pid}")
  PID_TO_EXPERIMENT["${pid}"]="${experiment_id}"
done

for pid in "${PIDS[@]}"; do
  experiment_id="${PID_TO_EXPERIMENT[$pid]}"

  if wait "${pid}"; then
    :
  else
    echo "[FAILED] ${experiment_id}"
    FAILED=1

    running_marker="${RUNNING_DIR}/${experiment_id}.running.json"
    failed_marker="${FAILED_DIR}/${experiment_id}.failed.json"
    log_file="${LOG_DIR}/${experiment_id}.log"

    rm -f "${running_marker}"

    mark_json \
      "${failed_marker}" \
      "failed" \
      "${experiment_id}" \
      "${CAMPAIGN_ID}__${experiment_id}" \
      "unknown" \
      "" \
      "$(date -Is)" \
      "${log_file}"
  fi
done

# ----------------------------------------------------------------------
# Summary
# ----------------------------------------------------------------------

completed_count="$(find "${COMPLETED_DIR}" -maxdepth 1 -type f -name '*.done.json' | wc -l)"
failed_count="$(find "${FAILED_DIR}" -maxdepth 1 -type f -name '*.failed.json' | wc -l)"
running_count="$(find "${RUNNING_DIR}" -maxdepth 1 -type f -name '*.running.json' | wc -l)"

{
  echo "campaign_id,total,completed,failed,running"
  echo "${CAMPAIGN_ID},${TOTAL},${completed_count},${failed_count},${running_count}"
} > "${SUMMARY_CSV}"

echo
echo "======================================================================"
echo "[CAMPAIGN] Summary"
echo "======================================================================"
echo "[CAMPAIGN] Campaign ID: ${CAMPAIGN_ID}"
echo "[CAMPAIGN] Total manifest rows: ${TOTAL}"
echo "[CAMPAIGN] Completed markers: ${completed_count}"
echo "[CAMPAIGN] Failed markers: ${failed_count}"
echo "[CAMPAIGN] Running markers: ${running_count}"
echo "[CAMPAIGN] Manifest: ${MANIFEST}"
echo "[CAMPAIGN] Summary CSV: ${SUMMARY_CSV}"
echo "[CAMPAIGN] Logs: ${LOG_DIR}"

if [[ "${FAILED}" -ne 0 ]]; then
  exit 1
fi

exit 0
